#!/bin/bash

# Parameters for train.py
export dl_args="-0.5 0.5 3"
# export basis_args="Def2-SVP"
export basis_args="cc-pVDZ"
export n_rad_args=""
export n_ang_args=""

## user's own commands below
export OMP_NUM_THREADS=24
export MKL_NUM_THREADS=24
export OPENBLAS_NUM_THREADS=24

export PID_THIS_RUN=$$

export PYSCF_MAX_MEMORY=80000
export PYTHONPATH=~/python:$PYTHONPATH
export LD_LIBRARY_PATH=~/anaconda3/lib:$LD_LIBRARY_PATH
export DFT2CC_CUBE_USE=3
export DFT2CC_GENERATE_DATA=1
export PYSCF_TMPDIR=~/raid/tmp

export NVIDIA_VISIBLE_DEVICES=1
# use less power GPU
# export CUDA_VISIBLE_DEVICES=$(nvidia-smi --query-gpu=power.draw,index --format=csv,nounits,noheader | sort -n | head -1 | awk '{ print $NF }')
# use most free memory GPU
export CUDA_VISIBLE_DEVICES=$(nvidia-smi --query-gpu=memory.free,index --format=csv,nounits,noheader | sort -n | tail -1 | awk '{ print $NF }')
# export CUDA_VISIBLE_DEVICES=NUMBER_OF_GPU

mkdir -p log
mkdir -p validate
mkdir -p data/grids_dft

if [ -z "$n_rad_args" ]; then
	export mol_args="--distance_list ${dl_args} --basis ${basis_args} --extend_atom 0-1 --extend_xyz 0"
else
	export mol_args="--distance_list ${dl_args} --basis ${basis_args} --n_rad ${n_rad_args} --n_ang ${n_ang_args} --extend_atom 0-1 --extend_xyz 0"
fi

nohup bash <<'EOF' >log/gen_data-${PID_THIS_RUN}.log 2>&1 &
set -e  # Exit on any error
~/anaconda3/envs/pyscf/bin/python gen_data.py ${mol_args} --name_mol G2RC-1 BH76-H2 FH51-Cl2 G21EA-EA_14n G21IP-IP_79 MRADC-cs-stretch GAPS-CaSe G2RC-24 G21IP-IP_78 GAPS-CaS G2RC-23 SIE4x4-he2+_1.5 SIE4x4-he2+_1.25 RG18-ar2 FH51-HCl HEAVY28-hbr SIE4x4-h2+_1.75 SIE4x4-h2+_1.0 NBPRC-H2 BH76-clf GW100-1333-74-0 GAPS-ScN SIE4x4-h2+_1.25 SIE4x4-he2+_1.75 GAPS-GaAs G21EA-EA_25n G21IP-IP_70 IDISP-h2 GAPS-GaP PA26-h2 MB16_43-H2 HEAVY28-hcl RG18-ne2 HEAVYSB11-br2 G2RC-47 G21IP-IP_80 FH51-H2 NBPRC-h2 G2RC-45 G21EA-EA_14 G2RC-22 G21EA-EA_25 HEAVYSB11-seh RG18-kr2 HEAVYSB11-cl2 G21EA-EA_23n SIE4x4-h2+_1.5 SIE4x4-he2+_1.0 G2RC-51 BH76-hcl GW100-124-38-9 G2RC-40 GAPS-LiZnP S66-16B BH9-06_1R2 S66-18A GAPS-LiZnAs S66-59B PA26-h2p S66-03A BH76-RKT01 S66-02A S66-12B G21EA-EA_15n S66-08B S66-01B S66-04A GAPS-CaF2 S66-54B BH9-09_13R1 GW100-75-15-0 BH9-03_8P2 BH76-hclhts BH76-RKT06 BH76-RKT17 S66-01A GAPS-MgCl2 G21EA-EA_15 AL2X6-alh3 S66-45A NBPRC-BH3 S66-50B MB16_43-AlH3 G2RC-57 GW100-13283-31-3 AL2X6-alcl3 RSE43-P1 GAPS-P G2RC-58 GAPS-CuGaO2 S66-65B BH76-ch3 NBPRC-BF3 HEAVYSB11-geh3 S66-51A FH51-COCl2 AL2X6-alf3 GAPS-CuAlO2 G21EA-EA_10n GAPS-ZnS G2RC-60 S66-32B G21EA-EA_16 S66-51B NBPRC-BCl3 NBPRC-bh3 GAPS-LiCoO2 S66-59A MB16_43-BH3 GAPS-CuScO2 GW100-7784-18-1 G21EA-EA_16n HEAVYSB11-h2se2 RC21-me G2RC-59 S66-60A BH76-RKT15 G2RC-97 G2RC-8 BSR36-ch4 RSE43-E1 G21IP-IP_64 S22-08a BH76-ch3cl G2RC-18 BH76-CH4 S22-10b MB16_43-CH4 S66-09B BH76-clch3clcomp BH76-fch3clcomp2 S66-33B BH76-hch3clts S66-06A BH76-ch3fclts BH76-fch3clcomp1 S66-02B S66-64B MRADC-c2h4-stretch S66-07A S66-31B S66-19A S66-08A S66-01 BH76-fch3clts S66-05A BH76-RKT08 S66-55B BH9-04_22P2 S66-30B S66-05B S66-13B BH9-04_23P2 BH76-clch3clts S30L-29B S66-44A S66-59 BH9-04_50P2 S66-06B G2RC-128 BH9-09_6R1 S66-11A ISO34-P1 RSE43-P8 BH9-08_1P2 S66-12A S66-56B S66-14B S66-09A S66-66A S66-10B S66-03B S66-10A S66-20A S66-51 RSE43-E8 S66-52B S66-60B HEAVYSB11-ge2h6 AL2X6-al2h6 S66-63B G2RC-52 S66-22A S66-20B S66-61B PA26-si2h6 S66-02 